/// The gallery's example of `SplitHandle`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_inverted = args.bool("inverted");
        let arg_label = args.text("label");

        let height = State::new(120.0_f32);
        // The size is yours to use; the bar only changes it.
        VStack::new((Text::new("Drag the bar, or focus it and use the arrow keys."), {
            let mut it = SplitHandle::new(Axis::Vertical, height.binding()).range(80.0, 300.0);
            if arg_inverted {
                it = it.inverted();
            }
            if !arg_label.is_empty() {
                it = it.label(arg_label.clone());
            }
            it
        }))
        .spacing(8.0)
        .align(Align::Stretch)
    })
}

impl ComponentBook for SplitHandle {
    fn book() -> Meta {
        Meta::new("Layout/SplitHandle", render)
            .summary("A bar to drag that changes a size.")
            .arg(ArgType::bool("inverted", true))
            .arg(ArgType::text("label", "").description("Empty leaves it as the component has it."))
            .story("Example", Args::new())
    }
}
